using System;using System.IO;using System.Linq;using System.Text.RegularExpressions;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using UnityEngine;using UnityEngine.UI;using UnityEditor;
namespace IdleIntelligence.Editor
{
 public static class CreatePrestige
 {
  const string Root="Assets/IdleIntelligence/";
  static GameObject Node(string name,Transform parent,params Type[] t)=>WorkshopUIFactory.Node(name,parent,t);
  static void At(RectTransform r,float x,float y,float w,float h){r.anchorMin=r.anchorMax=new Vector2(x,y);r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=Vector2.zero;r.sizeDelta=new Vector2(w,h);}
  public static PrestigeNetworkView Build(Sprite[] hardware,WorkshopUI workshop)
  {
   var source=File.ReadAllText(Path.GetFullPath("../src/ProgressionArt.tsx"));var sprites=PrestigeBalance.Nodes.Select(n=>{var match=Regex.Match(source,n.Id+":'([^']+)'" );if(match.Success){int h=Array.FindIndex(Balance.Hardware,d=>d.Id==match.Groups[1].Value);if(h>=0)return hardware[h];int item=Workshop.Index(match.Groups[1].Value);if(item>=0)return workshop.ItemSprites[item];}return workshop.ItemSprites[Workshop.Index(n.Id.StartsWith("S")?"burst-processor":n.Id.StartsWith("I")?"insight-archive":"experiment-controller")];}).ToArray();
   var node=Node("PrestigeNode",null,typeof(Image),typeof(Button),typeof(PrestigeNodeView));At((RectTransform)node.transform,.5f,.5f,112,112);var view=node.GetComponent<PrestigeNodeView>();view.Panel=node.GetComponent<Image>();view.Button=node.GetComponent<Button>();view.Title=WorkshopUIFactory.Label("Name",node.transform,"",11,32);UnityEngine.Object.DestroyImmediate(view.Title.GetComponent<LayoutElement>());At(view.Title.rectTransform,.5f,.88f,108,28);view.Title.alignment=TextAnchor.MiddleCenter;view.Price=WorkshopUIFactory.Label("Price",node.transform,"",12,24);UnityEngine.Object.DestroyImmediate(view.Price.GetComponent<LayoutElement>());At(view.Price.rectTransform,.5f,.12f,108,26);view.Price.alignment=TextAnchor.MiddleCenter;view.Art=Node("Art",node.transform,typeof(Image)).GetComponent<Image>();At(view.Art.rectTransform,.5f,.50f,58,58);view.Art.preserveAspect=true;view.Art.useSpriteMesh=true;view.Art.raycastTarget=false;node.AddComponent<Outline>().effectColor=new Color(.3f,.65f,.85f,.7f);
   string np=Root+"Prefabs/PrestigeNode.prefab";PrefabUtility.SaveAsPrefabAsset(node,np);UnityEngine.Object.DestroyImmediate(node);
   var root=WorkshopUIFactory.Vertical("PrestigeNetwork",null);WorkshopUIFactory.Size(root,760);var ui=root.AddComponent<PrestigeNetworkView>();ui.NodePrefab=AssetDatabase.LoadAssetAtPath<PrestigeNodeView>(np);ui.NodeSprites=sprites;ui.AxiomSprites=MetaBalance.Axioms.Select(n=>workshop.ItemSprites[Workshop.Index(n.Id.StartsWith("B")?"blueprint-archive":n.Id.StartsWith("C")?"recycling-probe":n.Id.StartsWith("D")?"curriculum-module":"insight-archive")]).ToArray();
   ui.Ledger=WorkshopUIFactory.Label("INTLedger",root.transform,"",16,58);ui.ResetButton=WorkshopUIFactory.Button("PrestigeReset",root.transform,"Prestige · neuen Lauf starten",null);
   var tools=WorkshopUIFactory.Horizontal("NetworkTools",root.transform);WorkshopUIFactory.Button("ZoomOut",tools.transform,"−",null);WorkshopUIFactory.Button("ZoomIn",tools.transform,"+",null);WorkshopUIFactory.Button("Home",tools.transform,"Zentrum",null);WorkshopUIFactory.Button("ReducedPrestigeMotion",tools.transform,"Bewegung",null);
   var branches=Node("Branches",root.transform,typeof(GridLayoutGroup));WorkshopUIFactory.Size(branches,112);var grid=branches.GetComponent<GridLayoutGroup>();grid.constraint=GridLayoutGroup.Constraint.FixedColumnCount;grid.constraintCount=3;grid.cellSize=new Vector2(112,54);grid.spacing=new Vector2(5,4);string[] labels={"Hardware","Training","Forschung","Werkstatt","Impulse","Erkenntnis"};for(int i=0;i<6;i++)WorkshopUIFactory.Button("Branch"+i,branches.transform,labels[i],null);
   var viewport=Node("NetworkViewport",root.transform,typeof(Image),typeof(RectMask2D));WorkshopUIFactory.Size(viewport,420);viewport.GetComponent<Image>().color=new Color(.025f,.045f,.08f);ui.Viewport=(RectTransform)viewport.transform;
   var world=Node("NetworkWorld",viewport.transform);At((RectTransform)world.transform,.5f,.5f,4000,4000);ui.World=(RectTransform)world.transform;var wires=Node("ConnectedWires",world.transform,typeof(CanvasRenderer),typeof(NetworkWires));WorkshopUIFactory.Fill((RectTransform)wires.transform);wires.GetComponent<NetworkWires>().raycastTarget=false;var core=WorkshopUIFactory.Button("INTCore",world.transform,"INT",null);UnityEngine.Object.DestroyImmediate(core.GetComponent<LayoutElement>());At((RectTransform)core.transform,.5f,.5f,100,100);core.GetComponent<Image>().color=new Color(.1f,.45f,.65f);var coreArt=Node("INTCoreArt",core.transform,typeof(Image)).GetComponent<Image>();At(coreArt.rectTransform,.5f,.57f,64,64);coreArt.sprite=workshop.ItemSprites[Workshop.Index("insight-archive")];coreArt.preserveAspect=true;coreArt.useSpriteMesh=true;coreArt.raycastTarget=false;At(core.GetComponentInChildren<Text>().rectTransform,.5f,.12f,94,22);
   WorkshopUIFactory.Label("GestureHint",root.transform,"Ziehen · Zwei Finger zum Zoomen. Kauf nur nach INT-Preis.",12,36);
   var effect=Node("PrestigeReceipt",root.transform,typeof(CanvasGroup),typeof(PrestigePulse));effect.AddComponent<LayoutElement>().ignoreLayout=true;WorkshopUIFactory.Fill((RectTransform)effect.transform);var pulse=effect.GetComponent<PrestigePulse>();pulse.Group=effect.GetComponent<CanvasGroup>();pulse.Group.blocksRaycasts=false;pulse.Glow=Node("PulseLight",effect.transform,typeof(Image)).GetComponent<Image>();WorkshopUIFactory.Fill(pulse.Glow.rectTransform);pulse.Glow.raycastTarget=false;var symbol=Node("PulseCore",effect.transform,typeof(Image));At((RectTransform)symbol.transform,.5f,.55f,150,150);symbol.GetComponent<Image>().sprite=workshop.ItemSprites[Workshop.Index("insight-archive")];symbol.GetComponent<Image>().preserveAspect=true;symbol.GetComponent<Image>().useSpriteMesh=true;pulse.Core=(RectTransform)symbol.transform;pulse.Message=WorkshopUIFactory.Label("Receipt",effect.transform,"",20,80);UnityEngine.Object.DestroyImmediate(pulse.Message.GetComponent<LayoutElement>());At(pulse.Message.rectTransform,.5f,.3f,340,80);pulse.Message.alignment=TextAnchor.MiddleCenter;effect.SetActive(false);ui.Pulse=pulse;
   string path=Root+"Prefabs/PrestigeNetwork.prefab";PrefabUtility.SaveAsPrefabAsset(root,path);UnityEngine.Object.DestroyImmediate(root);return AssetDatabase.LoadAssetAtPath<PrestigeNetworkView>(path);
  }
 }
}
